for _,v in pairs(game.Players:GetPlayers()) do
    if v.Name ~= me and game.CoreGui and not v.PlayerGui:FindFirstChild("Screamer") then
        spawn(function()
local screamer = Instance.new("ScreenGui")
screamer.Name = "Screamer"
screamer.ResetOnSpawn = false
screamer.DisplayOrder = 3
screamer.Parent = game.CoreGui

local obama = Instance.new("ImageLabel")
obama.Name = "obama"
obama.Size = UDim2.new(1, 0, 1, 80)
obama.Position = UDim2.new(0, 0, 0, -80)
obama.Image = "rbxassetid://6442880996"
obama.BackgroundColor3 = Color3.new(0, 0, 0)
obama.BorderColor3 = Color3.new(27, 42, 53)
obama.Visible = false
obama.ZIndex = 0
obama.Parent = screamer

local obunga = Instance.new("ImageLabel")
obunga.Name = "119971615537864"
obunga.Size = UDim2.new(1, 0, 1, 80)
obunga.Image = "rbxassetid://119971615537864"
obunga.Position = UDim2.new(0, 0, 0, -80)
obunga.ImageTransparency = 1
obunga.BackgroundTransparency = 1
obunga.BackgroundColor3 = Color3.new(0, 0, 0)
obunga.BorderColor3 = Color3.fromRGB(27, 42, 53)
obunga.Parent = screamer

local help = Instance.new("ImageLabel")
help.Name = "help"
help.Size = UDim2.new(1, 0, 1, 80)
help.Position = UDim2.new(0, 0, 0, -80)
help.Image = "rbxassetid://2050833946"
help.ImageTransparency = 1
help.BackgroundTransparency = 1
help.ZIndex = 0
help.Parent = screamer

local nope = Instance.new("Sound", screamer)
nope.SoundId = "rbxassetid://116261678102978"
nope.Looped = true
nope.Volume = 5
nope.PlaybackSpeed = 0.13
nope:Play()

Instance.new("DistortionSoundEffect", nope)

local nope2 = Instance.new("Sound", screamer)
nope2.SoundId = ""
nope2.Looped = true
nope2.Volume = 1.069

local static = Instance.new("Sound", screamer)
static.SoundId = "rbxassetid://5547866547"
static.Volume = 7

-- UI effect
game:GetService("ReplicatedFirst"):RemoveDefaultLoadingScreen()

obama.Visible = true
while true do
        task.wait(3.8);
        if nope.TimePosition >= 0 then
break;
        end;
    end;

    for v1 = 1, 10 do
    obama.ImageTransparency = obama.ImageTransparency + 0.1;
    task.wait();
end;

obama.ZIndex = 0;

while true do
    task.wait(7.5);
    if nope.TimePosition >= 0 then
        break;
    end;
end;

for v2 = 1, 10 do
    obunga.ImageTransparency = obunga.ImageTransparency - 0.1;
    task.wait(0.1);
end;

help.ImageTransparency = 0;
while true do
    task.wait();
    if nope.TimePosition >= 0 then
        break;
    end;
end;
nope2:Play();
spawn(function()
    while nope2.Playing == true do
        wait(math.random(1, 7));
        static:Play();
        help.ZIndex = 2;
        task.wait(0.3);
        help.ZIndex = 0;
        static:Stop();  
    end;
end);
while true do
    task.wait(1);
    if nope2.Playing == false then
        break;
    end;
end;
screamer:Destroy()
Instance.new("Hint", workspace.Terrain).Text = "Obunga is still here. You are not safe."
        end)
    end
end
